# Writes snowfall.txt: a seamless snowfall that never leaves the hill.
#
# Every flake falls inside a 2.8 m circle (the hill's top is a 9-gon of radius 3.3, its rim 3.1 m
# from the centre) and its fall ends just under the snow: below z 0 it is inside the hill's 0.5 m
# slab, hidden, and never falls into the void under the island.
#
# How: a column of flakes from B (-0.42) to B + D (7.08) is cut into K thin bands, one object (one
# bone) each. Every band falls at the same speed; when a band is entirely under the snow (between
# B and B + H, inside the slab) it jumps back to the top of the column, which is above the frame
# (the default 8.2 m ortho view shows at most ~6.8 m up, at the hill's front edge). The bands sit
# one band apart, so the union is a uniform column at every frame, and the loop (L s, every band
# falls the whole column once) has no seam. Jumps land on the 12 fps samples of the bake, so no
# sample catches a band in mid jump.
# Run: python3 make_snowfall.py
import math
import random

rnd = random.Random(7)
R = 2.8              # flakes inside this circle (m)
B = -0.42            # column bottom: under the snow, inside the slab (slab bottom -0.5, flake half-size 0.035)
K = 20               # bands (bones)
L = 15.0             # loop (s): one fall of the whole column
D = 7.5              # column height (m): 0.5 m/s
H = D / K            # band height 0.375: B + H + 0.035 < 0, so a band jumps only when all of it is hidden
N = 84               # flakes (the old field's density, ~11 a metre)
FPS = 24
F = round(L * FPS)   # 360
step = F // K        # 18 frames (0.75 s, a 12 fps sample) between the bands' jumps
assert F % K == 0 and step % 2 == 0 and B + H + 0.035 < 0 and B - 0.035 > -0.5

flakes = [[] for _ in range(K)]
n = 0
while n < N:
    x, y = rnd.uniform(-R, R), rnd.uniform(-R, R)
    if x * x + y * y > R * R:
        continue
    k = n % K        # stratified: every band gets its share
    flakes[k].append((x, y, B + (k + rnd.random()) * H))
    n += 1

v = D / L
lines = ["# Snowfall: generated by make_snowfall.py (see there). Up Z.", "new", f"fps {FPS}", f"frame range 0 {F}"]
groups = []
for k in range(K):
    names = []
    for i, (x, y, z) in enumerate(flakes[k]):
        nm = f"F{k}_{i}"
        lines.append(f"add mesh cube --name {nm} --size 0.07 --location {x:.3f} {y:.3f} {z:.3f}")
        names.append(nm)
    g = f"Snow{k:02d}"
    lines.append("select " + " ".join(names))
    lines.append(f"active {names[0]}")
    if len(names) > 1:
        lines.append("join")
    lines.append(f"rename {names[0]} {g}")
    lines.append("cursor set 0 0 0")
    lines.append("origin set --to cursor")
    groups.append(g)

lines.append("material new Flake --base-color 0.984 0.988 0.922 --emission 0.984 0.988 0.922")
lines.append("select " + " ".join(groups))
lines.append(f"active {groups[0]}")
lines.append("material assign Flake")

# keys: band k starts at B + k H (offset 0), falls to B at frame k * step, jumps to the column top
# one frame later, and falls back to its start at frame F. Band 0 starts at the top (offset +D).
for k, g in enumerate(groups):
    lines.append(f"select {g}")
    lines.append(f"active {g}")
    if k == 0:
        keys = [(0, D), (F, 0.0)]
    else:
        fj = k * step
        keys = [(0, 0.0), (fj, -k * H), (fj + 1, D - k * H - v / FPS), (F, 0.0)]
    for f, dz in keys:
        lines.append(f"set location 0 0 {dz:.5f}")
        lines.append(f"keyframe insert --channels loc --frame {f}")
lines.append("select " + " ".join(groups))
lines.append("keyframe interpolation linear --all")
lines.append("frame set 0")
lines.append("export snowfall.glb --bake-animations")
open("snowfall.txt", "w").write("\n".join(lines) + "\n")
print(f"{N} flakes in {K} bands of {H:.3f} m, column {B} .. {B + D:.2f} m, {L} s loop; per band:",
      [len(f) for f in flakes])
